package co.kr.badara.dolswevoice;
import android.app.*;import android.os.*;import java.io.*;import java.nio.*;import org.json.*;import com.k2fsa.sherpa.onnx.*;
public final class NativeSmoke extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private float[] wav(String name)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContext().getAssets().open(name)){byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}ByteBuffer b=ByteBuffer.wrap(out.toByteArray()).order(ByteOrder.LITTLE_ENDIAN);b.position(12);while(b.remaining()>=8){byte[] tag=new byte[4];b.get(tag);int n=b.getInt();if(new String(tag,"US-ASCII").equals("data")){float[] x=new float[n/2];for(int k=0;k<x.length;k++)x[k]=b.getShort()/32768f;return x;}b.position(b.position()+n+(n%2));}throw new IOException("No PCM data");}
 public void onStart(){Bundle report=new Bundle();SpeechEngine e=null;Vad vad=null;try{long start=System.currentTimeMillis();e=new SpeechEngine(getTargetContext().getAssets());vad=SpeechEngine.createVad(getTargetContext().getAssets());JSONArray results=new JSONArray();for(String file:new String[]{"dolswe.wav","imonim.wav","dolswe-slow.wav","imonim-slow.wav","negative.wav","negative-dolswe.wav"}){float[] x=wav(file);long before=System.currentTimeMillis();String text=e.recognize(x);CommandRouter.Wake wake=CommandRouter.wake(text,"돌쇠야, 이모님");if(wake.matched==file.startsWith("negative"))throw new AssertionError("Wake mismatch: "+file+" => "+text);results.put(new JSONObject().put("file",file).put("text",text).put("wake",wake.matched).put("decode_ms",System.currentTimeMillis()-before));}
 float[] a=wav("imonim.wav");for(int offset=0;offset<a.length;offset+=512){float[] frame=new float[512];System.arraycopy(a,offset,frame,0,Math.min(512,a.length-offset));vad.acceptWaveform(frame);}for(int k=0;k<32;k++)vad.acceptWaveform(new float[512]);if(vad.empty())throw new AssertionError("Neural VAD did not detect speech");report.putString("stream","NATIVE_OK "+results.toString()+" total_ms="+(System.currentTimeMillis()-start));finish(Activity.RESULT_OK,report);}catch(Throwable error){report.putString("stream","NATIVE_FAIL "+error.toString());finish(Activity.RESULT_CANCELED,report);}finally{if(vad!=null)vad.release();if(e!=null)e.close();}}
}
